Q1: Write a C program to add two matrices. Read the elements of two matrices and display the resulting matrix.

[Student Hand-Written Response - Page 1]:
1) C program to add two mxn matrices
#include <stdio.h>
int main () {
    int m, n;
    printf("Enter rows and columns mxn ");
    scanf("%d %d", &m, &n);
    int A[m][n], B[m][n], C[m][n];
    printf("Enter first matrix \n");
    for (int i=0; i<m; i++)
        for (int j=0; j<n; j++)
            scanf("%d", &A[i][j]);
    printf("Enter second matrix \n");
    for (int i=0; i<m; i++)
        for (int j=0; j<n; j++)
            scanf("%d", &A[i][j]);  // [Error: Scanned into &A[i][j] instead of &B[i][j]]

    // [Critical Omission: Matrix addition loop C[i][j] = A[i][j] + B[i][j] is missing]

    printf("sum of matrices :\n");
    for (int i=0; i<m; i++) {
        for (int j=0; j<n; j++)
            printf("%d ", C[i][j]);  // [Prints uninitialized array C]
        printf("\n");
    }
    return 0;
}

