Q1: Write a complete C program to find the roots of a quadratic equation by accepting coefficients a, b, and c from the user.

[Student Hand-Written Response - Page 1]:
1) Program to find roots of quadratic equation:
#include <stdio.h>
#include <math.h>

int main() {
    float a, b, c, d, r1, r2;
    printf("Enter coefficients a, b, c: ");
    scanf("%f %f %f", &a, &b, &c);
    if (a == 0) {
        printf("Invalid input. Not a quadratic equation.\n");
        return 0;
    }
    d = (b * b) - (4 * a * c);
    if (d > 0) {
        r1 = (-b + sqrt(d)) / (2 * a);
        r2 = (-b - sqrt(d)) / (2 * a);
        printf("Roots are real and distinct: %f %f\n", r1, r2);
    } else if (d == 0) {
        r1 = -b / (2 * a);
        printf("Roots are real and equal: %f\n", r1);
    } else {
        printf("Roots are imaginary\n");
    }
    return 0;
}

